            readback_data_var[0] = field_storage.PPCFG.PP_EN.value;
            readback_data_var[1] = field_storage.PPCFG.RELU.value;
            readback_data_var[2] = field_storage.PPCFG.ROUND.value;
            readback_data_var[12:8] = field_storage.PPCFG.SHIFT.value;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
